import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Gestores de archivos compatibles","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/file-manager-support.md","filePath":"es-ES/user-guide/file-manager-support.md","lastUpdated":1785993908000}'),i={name:"es-ES/user-guide/file-manager-support.md"};function d(r,e,l,s,c,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="gestores-de-archivos-compatibles" tabindex="-1">Gestores de archivos compatibles <a class="header-anchor" href="#gestores-de-archivos-compatibles" aria-label="Permalink to &quot;Gestores de archivos compatibles&quot;">​</a></h1><p>Lertaro no solo busca — también puede integrarse con el gestor de archivos o el diálogo que estés usando en ese momento. Según el destino, esa integración puede significar hasta tres cosas:</p><ul><li><strong>Acoplamiento de búsqueda en línea</strong> — una barra de búsqueda de Lertaro se incrusta directamente en la ventana de destino (la <a href="./getting-started.html#las-tres-ventanas">ventana en línea</a>), de modo que puedas buscar sin salir de ella.</li><li><strong>Navegación rápida</strong> — el destino responde a los <a href="./hotkeys.html#navegacion-rapida-raton">disparadores de ratón de navegación rápida</a> (doble clic/clic central, o el propio logotipo de la ventana en línea), mostrando un menú en cascada de Favoritos, Historial y carpetas de acceso rápido.</li><li><strong>Detección de ruta activa</strong> — Lertaro puede saber qué carpeta está abierta en ese momento en el destino, de modo que pueda restringir una búsqueda a esa carpeta y resolver acciones relativas a la ruta (como Copiar ruta) contra ella.</li></ul><p>No todas las integraciones ofrecen las tres — ver la tabla de abajo.</p><h2 id="integrado-sin-instalacion-adicional" tabindex="-1">Integrado (sin instalación adicional) <a class="header-anchor" href="#integrado-sin-instalacion-adicional" aria-label="Permalink to &quot;Integrado (sin instalación adicional)&quot;">​</a></h2><p>Estos vienen incluidos con el plugin de extensiones básicas de Lertaro — nada que habilitar por separado.</p><table tabindex="0"><thead><tr><th>Destino</th><th>Acoplamiento de búsqueda en línea</th><th>Navegación rápida</th><th>Detección de ruta activa</th></tr></thead><tbody><tr><td>Explorador de archivos de Windows</td><td>Sí</td><td>Doble clic o clic central</td><td>Sí</td></tr><tr><td>Diálogo moderno Abrir/Guardar</td><td>Sí (esto <em>es</em> la ventana en línea)</td><td>Clic central, o clic izquierdo en el propio logotipo de la ventana en línea</td><td>—</td></tr><tr><td>Diálogo clásico Abrir/Guardar</td><td>Sí</td><td>Clic central, o clic izquierdo en el propio logotipo de la ventana en línea</td><td>—</td></tr><tr><td>Diálogo clásico Examinar carpetas</td><td>Sí</td><td>Clic central, o clic izquierdo en el propio logotipo de la ventana en línea</td><td>—</td></tr></tbody></table><p>La detección de ruta activa no se aplica a los propios diálogos — no hay &quot;otra ventana&quot; contra la que Lertaro pueda restringir una búsqueda una vez que ya está acoplado dentro del diálogo.</p><h2 id="plugins-opcionales-configuracion-→-plugins" tabindex="-1">Plugins opcionales (Configuración → Plugins) <a class="header-anchor" href="#plugins-opcionales-configuracion-→-plugins" aria-label="Permalink to &quot;Plugins opcionales (Configuración → Plugins)&quot;">​</a></h2><p>Cada uno de estos se distribuye como su propio plugin. Instálalo/habilítalo desde <a href="./settings/plugins.html">Configuración → Plugins</a>, y luego usa el propio diálogo <strong>Configurar</strong> de ese plugin para activar <strong>Habilitar búsqueda en línea</strong> y <strong>Habilitar navegación rápida</strong> de forma independiente — ambos vienen activados por defecto.</p><table tabindex="0"><thead><tr><th>Destino</th><th>Acoplamiento de búsqueda en línea</th><th>Navegación rápida</th><th>Detección de ruta activa</th></tr></thead><tbody><tr><td>Directory Opus</td><td>Sí</td><td>Clic central en un panel de lista de archivos</td><td>Sí</td></tr><tr><td>Files</td><td>Sí</td><td>Clic central en un panel de lista de archivos</td><td>Sí</td></tr><tr><td>One Commander</td><td>Sí</td><td>Clic central en un panel de lista de archivos</td><td>Sí</td></tr><tr><td>Total Commander</td><td>Sí</td><td>Clic central en un panel de lista de archivos</td><td>Sí</td></tr><tr><td>XYplorer</td><td>Sí</td><td>Clic central en un panel de lista de archivos</td><td>Sí</td></tr></tbody></table><p>Los cinco detectan su destino haciendo coincidir el proceso en ejecución (y, en el caso de Directory Opus y Total Commander, comunicándose con su interfaz de control remoto documentada a través de <code>WM_COPYDATA</code>, en lugar de leer la interfaz); Files y One Commander usan en su lugar UI Automation, ya que ninguno expone un protocolo de control remoto.</p><h2 id="dialogos-propios-de-aplicaciones-plugins-opcionales" tabindex="-1">Diálogos propios de aplicaciones (plugins opcionales) <a class="header-anchor" href="#dialogos-propios-de-aplicaciones-plugins-opcionales" aria-label="Permalink to &quot;Diálogos propios de aplicaciones (plugins opcionales)&quot;">​</a></h2><p>Estos apuntan a un diálogo concreto dentro de una aplicación de terceros — no a la aplicación entera — de la misma forma que hacen los diálogos integrados de arriba. Instálalo/habilítalo desde <a href="./settings/plugins.html">Configuración → Plugins</a>; cada uno distribuye un único componente con su propio interruptor de encendido/apagado ahí (sin diálogo Configurar independiente, ya que solo hay una cosa que activar o desactivar).</p><table tabindex="0"><thead><tr><th>Destino</th><th>Acoplamiento de búsqueda en línea</th><th>Navegación rápida</th><th>Detección de ruta activa</th></tr></thead><tbody><tr><td>Diálogo Abrir/Guardar de WPS Office</td><td>Sí</td><td>Clic central, o clic izquierdo en el propio logotipo de la ventana en línea</td><td>—</td></tr><tr><td>Diálogo Extraer de WinRAR</td><td>Sí</td><td>Clic central, o clic izquierdo en el propio logotipo de la ventana en línea</td><td>—</td></tr><tr><td>Diálogo Extraer de Bandizip</td><td>Sí</td><td>Clic central, o clic izquierdo en el propio logotipo de la ventana en línea</td><td>—</td></tr><tr><td>Diálogo Añadir archivos de Bandizip</td><td>Sí</td><td>Clic central, o clic izquierdo en el propio logotipo de la ventana en línea</td><td>—</td></tr></tbody></table><p>Se detectan por estructura de controles, no por título de ventana, así que esto funciona en todos los paquetes de idioma que distribuye cada aplicación. La entrada de WPS cubre Writer, Hojas de cálculo, Presentación y el lector de PDF, que comparten el mismo diálogo: WPS usa el suyo propio en lugar del de Windows, y por eso necesita un plugin, mientras que la mayoría de aplicaciones quedan cubiertas por los diálogos integrados de arriba. Igual que con ellos, la detección de ruta activa no se aplica — Lertaro ya está acoplado dentro del propio diálogo, sin ninguna otra ventana contra la que restringir una búsqueda.</p><hr><p>¿Vas a crear tu propia integración para un gestor de archivos que no aparece aquí? Consulta la referencia de <a href="./../dev-guide/sdk/system-adapters.html">Adaptadores de sistema y de diálogo</a> en el Manual de Desarrollador.</p>',18)])])}const h=a(i,[["render",d]]);export{g as __pageData,h as default};
